setup_files.main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_autoscaling_group" "web" {
  name                = "web-asg"
  min_size            = 2
  max_size            = 6
  desired_capacity    = 2
  vpc_zone_identifier = ["subnet-aaaa", "subnet-bbbb"]
  health_check_type   = "EC2"

  launch_template {
    id      = "lt-0123456789abcdef0"
    version = "$Latest"
  }
}

